async (page) => {
 const key='__switchLampDeployed';
 if(globalThis[key]) throw new Error('Owned smoke already exists.');
 const browser=page.context().browser();
 const context=await browser.newContext({viewport:{width:1440,height:900}});
 const p=await context.newPage();
 const hashContext=await browser.newContext({serviceWorkers:'block'});
 await hashContext.route('**/*',route=>route.request().url()==='https://p025-smoke-hash.invalid/'?route.fulfill({status:200,contentType:'text/html',body:'<!doctype html><title>Identity hash</title>'}):route.abort());
 const hashPage=await hashContext.newPage();await hashPage.goto('https://p025-smoke-hash.invalid/');
 const expected={}; const declared={};for(const name of ["_framework/CuriousContraptions.wasm","_framework/CuriousContraptions.web.wasm","_framework/dotnet.boot.js","godot.pck","simulation/_framework/CuriousContraptions.Simulation.wasm","simulation/_framework/dotnet.boot.js","animation/_framework/CuriousContraptions.Animation.Worker.wasm","animation/_framework/dotnet.boot.js","simulation/physics.wgsl","simulation/worker.js","animation/worker.js","workshop-client.js","workshop-isolation.js"]){const response=await p.request.get('https://aidanmorgan.github.io/tim/'+name);if(!response.ok())throw Error('Artifact unavailable '+name);const body=await response.body();const sha256=await hashPage.evaluate(async b=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',Uint8Array.from(atob(b),c=>c.charCodeAt(0)))),x=>x.toString(16).padStart(2,'0')).join(''),body.toString('base64'));if(declared[name]&&sha256!==declared[name])throw Error('Frozen artifact mismatch '+name);expected[name]={bytes:body.length,sha256};}
 const state={context,page:p,hashContext,hashPage,expected,console:[],errors:[],identities:[],workers:[],pending:new Set(),start:Date.now(),closed:false};
 globalThis[key]=state;p.__genericDiag=state;
 const path=url=>url.startsWith('https://aidanmorgan.github.io/tim/')?url.slice('https://aidanmorgan.github.io/tim/'.length):null;
 p.on('console',m=>{const t=m.text();if(state.console.length>=2048||t.length>24000){state.errors.push('Console cap');return;}state.console.push({at:Date.now(),type:m.type(),text:t});});
 p.on('pageerror',e=>state.errors.push('Page: '+e.message));
 p.on('worker',w=>{const row={url:w.url(),created:Date.now(),closed:null};state.workers.push(row);w.on('close',()=>row.closed=Date.now());});
 const onFinished=req=>{
   const name=path(req.url());if(!expected[name])return;
   if(state.identities.length+state.pending.size>=52){state.errors.push('Identity count cap');return;}
   const task=(async()=>{
     const response=await req.response();if(!response||response.status()!==200||response.url()!==req.url()||req.redirectedFrom())throw new Error('Bad loaded response '+name);
     let body=await response.body();const rawBodyBytes=body.length;let adapter=null;if(name==='simulation/physics.wgsl'&&body.length===expected[name].bytes+2){body=body.constructor.from(body.toString('utf8'),'latin1');adapter='CDP text/wgsl Latin1-to-UTF8 reencoding reversed; established exact original shader proof';}if(body.length>1048576)throw new Error('Selected resource exceeds1MiB');
     const digest=await hashPage.evaluate(async base64=>{const bin=atob(base64);const b=Uint8Array.from(bin,c=>c.charCodeAt(0));return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',b)),x=>x.toString(16).padStart(2,'0')).join('');},body.toString('base64'));
     const row={path:name,url:req.url(),bytes:body.length,rawBodyBytes,adapter,sha256:digest,fromServiceWorker:response.fromServiceWorker(),timing:req.timing(),match:body.length===expected[name].bytes&&digest===expected[name].sha256};
     state.identities.push(row);if(!row.match)state.errors.push('Loaded mismatch '+name);
   })().catch(e=>state.errors.push(e.message)).finally(()=>state.pending.delete(task));
   state.pending.add(task);
 };
 p.on('requestfinished',onFinished);state.onFinished=onFinished;
 await p.bringToFront();
 await p.goto('https://aidanmorgan.github.io/tim/',{waitUntil:'domcontentloaded',timeout:15000});
 const until=Date.now()+18000;
 while(Date.now()<until){
   if(state.console.some(x=>/CCGPU_TRANSPORT_FAILURE|CCGPU_STARTUP_EXCEPTION|CCGPU_INITIALIZE_EXCEPTION|StartupFailed/.test(x.text))||state.errors.length)break;
   if(Object.keys(expected).every(n=>state.identities.some(x=>x.path===n&&x.match))&&state.workers.filter(x=>x.closed===null).length===2&&Date.now()-state.start>4000){const e=await p.evaluate(async()=>{const m=await import('/tim/workshop-isolation.js');return m.isolationEvidence();});state.serving=e;if(e.phase===2)break;}
   await p.waitForTimeout(100);
 }
 state.setupAt=Date.now();
 state.isolation=await p.evaluate(()=>({url:location.href,crossOriginIsolated,controller:navigator.serviceWorker.controller?.scriptURL,visibility:document.visibilityState}));
 try{state.admission=await p.evaluate(async()=>{const m=await import('/tim/workshop-client.js');return{status:m.status(1),mode:m.captureMode(1),animationQualified:m.animationQualified(1),peer:Array.from(m.bootstrap(1))};});}catch(e){state.admissionError=e.message;}
 state.screenshot=(await p.screenshot({type:'png'})).toString('base64');
 await Promise.race([Promise.allSettled([...state.pending]),p.waitForTimeout(2000)]); p.off('requestfinished',onFinished);await hashContext.close();state.hashClosed=true;
 return {start:state.start,setupAt:state.setupAt,identities:state.identities,missing:Object.keys(expected).filter(n=>!state.identities.some(x=>x.path===n&&x.match)),console:state.console,errors:state.errors,workers:state.workers,isolation:state.isolation,serving:state.serving,admission:state.admission,admissionError:state.admissionError,pending:state.pending.size,hashClosed:state.hashClosed,ownedContextLive:!state.closed,screenshot:state.screenshot};
}
